"""Output-only checks for the revised recurrence-priority benchmark.

Run with OUTPUT_DIR=/absolute/output python -m pytest test_outputs.py.
Uses only final deliverables and embedded reference facts; never imports the
solution, reads source data at verification time, or accesses the network.
Narrative recommendation semantics and source-reconciliation justifications
remain rubric judgments. Passing these checks is not a platform rubric score.
"""
import csv
import json
import os
import re
from collections import defaultdict
from decimal import Decimal, InvalidOperation
from pathlib import Path

OUTPUT = Path(os.environ.get('OUTPUT_DIR', '/workspace/output'))
SUMMARY_FIELDS = {'MINE_ID','CURRENT_MINE_NAME','PRIORITY_RANK','TOTAL_HOURS',
    'HOURS_YEARS_REPORTED','SERIOUS_RECORDS','INJURY_RATE','TOTAL_VIOLATIONS',
    'SS_VIOLATIONS','TOTAL_INSPECTIONS','SS_INSPECTION_EVENTS','SS_EVENT_YEARS',
    'QUALIFYING_SS_VIOLATIONS'}
SENSITIVITY_FIELDS = {'SCENARIO_ID','ASSUMPTION_CHANGE','SELECTED_MINE_ID',
    'SELECTED_MINE_NAME','SS_INSPECTION_EVENTS','SELECTION_CHANGED','LIMITATION'}
DECISION = ('SS_INSPECTION_EVENTS','SS_EVENT_YEARS','QUALIFYING_SS_VIOLATIONS')
COUNT_FIELDS = ('SERIOUS_RECORDS','TOTAL_VIOLATIONS','SS_VIOLATIONS',
    'TOTAL_INSPECTIONS','HOURS_YEARS_REPORTED',*DECISION)
WINNER = '2300758'


def read_text(relative):
    path = OUTPUT / relative
    assert path.is_file(), f'Missing file: {relative}'
    text = path.read_text(encoding='utf-8-sig')
    assert text.strip(), f'Empty file: {relative}'
    return text


def read_csv(relative, required):
    read_text(relative)
    with (OUTPUT/relative).open(encoding='utf-8-sig',newline='') as stream:
        reader=csv.DictReader(stream)
        header=reader.fieldnames or []
        assert len(header)==len(set(header)), f'Duplicate CSV headers: {relative}'
        assert required <= set(header), f'Missing columns in {relative}: {required-set(header)}'
        rows=list(reader)
    assert rows, f'Empty CSV: {relative}'
    assert all(None not in row and all(v is not None for v in row.values()) for row in rows), 'Malformed CSV row'
    return rows


def summary():
    return read_csv('analysis/summary.csv',SUMMARY_FIELDS)


def sensitivity():
    return read_csv('analysis/sensitivity.csv',SENSITIVITY_FIELDS)


def number(value,label,integer=False,nullable=False):
    value=value.strip()
    if nullable and not value:
        return None
    try:
        n=Decimal(value)
    except InvalidOperation:
        raise AssertionError(f'{label}: not numeric: {value!r}') from None
    assert n.is_finite() and n>=0, f'{label}: must be finite and nonnegative'
    if integer:
        assert n==n.to_integral_value(), f'{label}: must be an integer'
    return n


def normalize_name(value):
    return ' '.join(value.replace('\u2019',"'").split()).casefold()


def expected(row):
    mid=row['MINE_ID']
    assert mid in REFERENCE, f'Unknown or out-of-scope mine ID: {mid!r}'
    return REFERENCE[mid]


def quality():
    def no_duplicates(pairs):
        obj={}
        for key,value in pairs:
            assert key not in obj, f'Duplicate JSON key: {key}'
            obj[key]=value
        return obj
    def reject_constant(value):
        raise AssertionError(f'Non-standard JSON constant: {value}')
    obj=json.loads(read_text('analysis/data_quality.json'),object_pairs_hook=no_duplicates,parse_constant=reject_constant)
    assert isinstance(obj,dict), 'Data quality must be a JSON object'
    for key in ['source_coverage','reconciliation_findings','excluded_records','unresolved_issues']:
        assert key in obj and isinstance(obj[key],list), f'{key} must be an array'
    return obj


def test_memo_exists_and_is_nonempty():
    read_text('recommendation.md')


def test_memo_contains_correct_operation_identity():
    # Presence only. A rubric judge assesses which operation the prose recommends.
    # No mandated heading, paragraph position, phrase, or punctuation.
    text=read_text('recommendation.md')
    assert re.search(r'(?<!\d)2300758(?!\d)',text), 'Correct mine ID absent from memo'
    normalized=normalize_name(re.sub(r'[*_`]', '', text))
    assert normalize_name(REFERENCE[WINNER]['name']) in normalized, 'Correct full mine name absent'


def test_summary_columns():
    summary()


def test_summary_complete_unique_known_mines():
    rows=summary();ids=[r['MINE_ID'] for r in rows]
    assert len(ids)==len(set(ids)), 'Duplicate mine IDs'
    assert set(ids)==set(REFERENCE), 'Summary must cover all eligible mines and no invented mines'


def test_summary_names_match_mine_ids():
    for row in summary():
        assert normalize_name(row['CURRENT_MINE_NAME'])==normalize_name(expected(row)['name']), 'Mine name/ID mismatch'


def test_summary_count_domains():
    for row in summary():
        for column in COUNT_FIELDS:
            number(row[column],column,integer=True)
        assert number(row['HOURS_YEARS_REPORTED'],'hours years')<=3
        assert number(row['SS_EVENT_YEARS'],'event years')<=3
        assert number(row['PRIORITY_RANK'],'rank',integer=True)>=1


def test_summary_exposure_matches_reported_records():
    for row in summary():
        ref=expected(row)
        hours=number(row['TOTAL_HOURS'],'hours',nullable=True)
        assert hours == (Decimal(ref['hours']) if ref['hours'] is not None else None), f'Incorrect reported hours: {row["MINE_ID"]}'
        assert number(row['HOURS_YEARS_REPORTED'],'hours years',integer=True)==ref['hours_years']


def test_summary_violation_totals_match_reference():
    for row in summary():
        ref=expected(row)
        assert number(row['TOTAL_VIOLATIONS'],'violations',integer=True)==ref['violations']
        assert number(row['SS_VIOLATIONS'],'S&S violations',integer=True)==ref['ss']


def test_summary_event_counts_within_reconciled_reference_bounds():
    # Bounds accommodate reported/start/end-year interpretations in shipped data.
    # The rubric must still assess whether the chosen interpretation is justified.
    mapping={'TOTAL_INSPECTIONS':'inspection_bounds','SS_INSPECTION_EVENTS':'event_bounds',
             'SS_EVENT_YEARS':'year_bounds','QUALIFYING_SS_VIOLATIONS':'linked_ss_bounds'}
    for row in summary():
        ref=expected(row)
        for field,key in mapping.items():
            low,high=ref[key]
            value=number(row[field],field,integer=True)
            assert low<=value<=high, f'{row["MINE_ID"]}: {field} outside documented reconciliation bounds'


def test_summary_count_relationships():
    for row in summary():
        n={c:number(row[c],c,integer=True) for c in COUNT_FIELDS}
        assert n['SS_INSPECTION_EVENTS']<=n['TOTAL_INSPECTIONS']
        assert n['SS_EVENT_YEARS']<=n['SS_INSPECTION_EVENTS']
        assert n['SS_INSPECTION_EVENTS']<=n['QUALIFYING_SS_VIOLATIONS']<=n['SS_VIOLATIONS']<=n['TOTAL_VIOLATIONS']
        assert (n['SS_INSPECTION_EVENTS']==0)==(n['SS_EVENT_YEARS']==0)


def test_injury_rates_are_finite_and_six_decimal_places():
    for row in summary():
        value=row['INJURY_RATE'].strip()
        if value:
            number(value,'injury rate')
            assert re.fullmatch(r'\d+\.\d{6}',value), 'INJURY_RATE must have six decimal places'


def test_injury_rates_match_stated_counts_and_hours():
    for row in summary():
        rate=number(row['INJURY_RATE'],'rate',nullable=True)
        hours=number(row['TOTAL_HOURS'],'hours',nullable=True)
        count=number(row['SERIOUS_RECORDS'],'injury records',integer=True)
        if rate is not None:
            assert hours is not None and hours>0, 'Rate has no positive exposure denominator'
            assert abs(rate-count*Decimal(200000)/hours)<=Decimal('0.0000005'), 'Rate inconsistent with reported count and hours'
    # Missing rate justification and accident-category choice are judged from memo.


def test_ranks_follow_policy_and_preserve_ties():
    rows=summary()
    pairs=[(tuple(number(r[c],c,integer=True) for c in DECISION),
            number(r['PRIORITY_RANK'],'rank',integer=True)) for r in rows]
    groups=defaultdict(list)
    for key,rank in pairs:groups[key].append(rank)
    ordered=sorted(groups,reverse=True)
    rank_values=[];competition=[];position=1
    for key in ordered:
        assert len(set(groups[key]))==1, 'Identical policy criteria must share a rank'
        rank_values.append(groups[key][0]);competition.append(position);position+=len(groups[key])
    # Instructions allow shared ranks but prescribe no dense/competition convention.
    assert rank_values==competition or rank_values==list(range(1,len(ordered)+1)), 'Ranks do not follow policy'


def test_summary_correct_sole_first_place():
    winners=[r for r in summary() if number(r['PRIORITY_RANK'],'rank',integer=True)==1]
    assert len(winners)==1 and winners[0]['MINE_ID']==WINNER, 'Incorrect first-place operation'
    assert number(winners[0]['SS_INSPECTION_EVENTS'],'events',integer=True)==13


def test_sensitivity_columns_and_scenarios():
    rows=sensitivity()
    groups=defaultdict(list)
    for row in rows:
        assert row['SCENARIO_ID'].strip(), 'Missing scenario ID'
        assert row['ASSUMPTION_CHANGE'].strip() and row['LIMITATION'].strip(), 'Missing scenario description/limitation'
        groups[row['SCENARIO_ID']].append(row)
    assert len(groups)>=2, 'A baseline and alternative scenario are required'
    for items in groups.values():
        ids=[r['SELECTED_MINE_ID'] for r in items]
        assert len(ids)==len(set(ids)), 'Duplicate operation within a scenario'
        assert len({r['ASSUMPTION_CHANGE'] for r in items})==1, 'One scenario ID describes different assumptions'
    # Narrative baseline labeling is not constrained to one specific token.


def test_sensitivity_identities_and_numeric_domains():
    for row in sensitivity():
        mid=row['SELECTED_MINE_ID']
        assert mid in REFERENCE, f'Unknown sensitivity mine: {mid}'
        assert normalize_name(row['SELECTED_MINE_NAME'])==normalize_name(REFERENCE[mid]['name'])
        events=number(row['SS_INSPECTION_EVENTS'],'scenario events',integer=True)
        assert events<=REFERENCE[mid]['all_ss_events'], 'Scenario invents S&S events beyond source records'
        assert row['SELECTION_CHANGED'] in {'true','false'}, 'Invalid selection-change token'


def test_sensitivity_change_flags_match_selected_set():
    rows=sensitivity();groups=defaultdict(list)
    for row in rows:groups[row['SCENARIO_ID']].append(row)
    found_baseline_result=False
    for items in groups.values():
        changed={r['SELECTED_MINE_ID'] for r in items}!={WINNER}
        assert all(r['SELECTION_CHANGED']==str(changed).lower() for r in items), 'Selection-change flag contradicts selected operations'
        if not changed and all(number(r['SS_INSPECTION_EVENTS'],'events',integer=True)==13 for r in items):
            found_baseline_result=True
    assert found_baseline_result, 'Sensitivity output lacks the baseline result'


